CREATE OR REPLACE FUNCTION public.kioskd_emergency_progress(p_token text,p_pin text) RETURNS TABLE(total integer,accounted integer,outstanding integer,drill_title text,event_class text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE site uuid; BEGIN site:=public.kiosk_device_site(p_token); PERFORM public.kiosk_emergency_gate(p_pin,'progress'); RETURN QUERY SELECT count(*)::integer,count(*) FILTER(WHERE public.emergency_is_accounted(a.status,a.outcome,a.confirmation_method,a.confirmed_at))::integer,count(*) FILTER(WHERE NOT public.emergency_is_accounted(a.status,a.outcome,a.confirmation_method,a.confirmed_at))::integer,d.title,d.event_class FROM public.evacuation_attendance a JOIN public.evacuation_drills d ON d.id=a.drill_id WHERE d.branch_id=site AND d.state IN ('active','paused') GROUP BY d.id,d.title,d.event_class; END $$;
REVOKE EXECUTE ON FUNCTION public.kiosk_emergency_progress(text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.emergency_trusted_actor() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.outcome IS NOT NULL THEN NEW.confirmed_by:=CASE WHEN NEW.confirmed_at IS NOT NULL THEN auth.uid() END; NEW.marked_by:=coalesce(auth.uid()::text,'Kiosk (PIN)'); IF NEW.confirmed_at>now()+interval '1 minute' THEN RAISE EXCEPTION 'Confirmation time cannot be in the future'; END IF; IF NEW.outcome<>'physically_safe' THEN NEW.marked_safe_at:=NULL; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.emergency_trusted_actor() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER z_trusted_emergency_actor BEFORE INSERT OR UPDATE ON public.evacuation_attendance FOR EACH ROW EXECUTE FUNCTION public.emergency_trusted_actor();